def max_element(l: list):
    """Return maximum element in the list.
    >>> max_element([1, 2, 3])
    3
    >>> max_element([5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10])
    123
    """
    if not l:
        raise ValueError("max_element() arg is an empty list")
    return max(l)

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        raise ValueError("n must be greater than 1")
    # Find the smallest divisor greater than 1
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i
    # n is prime, the largest proper divisor is 1
    return 1

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def add(lst):
    """Given a non-empty list of integers lst. add the even elements that are at odd indices..

    Examples:
        add([4, 2, 6, 7]) ==> 2 
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 2 == 1 and val % 2 == 0:
            total += val
    return total

from collections import Counter
def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string by whitespace to get individual letters.
    # Using split() handles any amount of whitespace and discards empty strings.
    letters = test.split()

    # If there are no letters, return an empty dictionary.
    if not letters:
        return {}

    # Count the occurrences of each letter using collections.Counter.
    counts = Counter(letters)

    # Determine the maximum count.
    max_count = max(counts.values())

    # Build a dictionary of all letters that have the maximum count.
    result = {letter: max_count for letter, cnt in counts.items() if cnt == max_count}

    return result

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    # Work with the absolute value to ignore the sign
    n = abs(num)

    # Special case for zero: it has one even digit and no odd digits
    if n == 0:
        return (1, 0)

    even = 0
    odd = 0
    while n > 0:
        digit = n % 10
        if digit % 2 == 0:
            even += 1
        else:
            odd += 1
        n //= 10

    return (even, odd)

import hashlib
def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()
